class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

class Solution:
    def str2tree(self, s: str) -> TreeNode:
        if not s:
            return None
        self.i = 0
        def parse():
            if self.i >= len(s):
                return None
            sign = 1
            if s[self.i] == '-':
                sign = -1
                self.i += 1
            num = 0
            while self.i < len(s) and s[self.i].isdigit():
                num = num * 10 + int(s[self.i])
                self.i += 1
            node = TreeNode(sign * num)
            if self.i < len(s) and s[self.i] == '(':
                self.i += 1
                node.left = parse()
                self.i += 1
            if self.i < len(s) and s[self.i] == '(':
                self.i += 1
                node.right = parse()
                self.i += 1
            return node
        return parse()

